import React, { useEffect, useMemo, useRef, useState } from "react";
import { AccessibilityInfo, PanResponder, View, type ViewStyle } from "react-native";
import {
  Canvas,
  Fill,
  FilterMode,
  ImageShader,
  LinearGradient,
  MipmapMode,
  Path,
  Rect,
  RoundedRect,
  Skia,
  Vertices,
  vec,
  type SkImage,
} from "@shopify/react-native-skia";
import { useDerivedValue, useFrameCallback, useSharedValue } from "react-native-reanimated";
import { createWorld, shardGlint, shardRefraction, stepWorld, type World } from "./shatterMath";

export type GlassShatterProps = {
  /** The picture behind the glass, drawn at `imageScale` pixels per point. */
  image: SkImage;
  imageScale?: number;
  width?: number;
  height?: number;
  /** About how many shards the pane breaks into. */
  shardCount?: number;
  /** Runs the fall about four times slower. Ignored while Reduce Motion is on. */
  slowMotion?: boolean;
  reducedMotion?: boolean;
  /** Change this number to put a fresh, whole pane back (same as the Reset button). */
  resetToken?: number;
  /** Fired with "hit" when the pane is struck (hook haptics here). */
  onFeedback?: (event: "hit") => void;
  label?: string;
  style?: ViewStyle;
};

type Ev = { id: number; k: number; x: number; y: number };
type Mesh = { xy: { x: number; y: number }[]; tex: { x: number; y: number }[]; tint: { x: number; y: number }[]; path: ReturnType<typeof Skia.Path.Make> };

// Android stops presenting a canvas whose only change is internal on an idle
// screen. A 1 px layout change every frame keeps it drawing.
function CanvasKeepAlive() {
  const [beat, setBeat] = useState(0);
  useEffect(() => {
    let cancelled = false;
    const tick = () => {
      if (cancelled) return;
      setBeat((b) => b + 1);
      requestAnimationFrame(tick);
    };
    const id = requestAnimationFrame(tick);
    return () => {
      cancelled = true;
      cancelAnimationFrame(id);
    };
  }, []);
  return (
    <View
      pointerEvents="none"
      style={{ position: "absolute", width: 1, height: 1, opacity: 0, transform: [{ translateX: beat % 2 }] }}
    />
  );
}

// One-pixel strip: pixel x is white with alpha x/255 * 0.5. Each vertex maps its
// glint into the strip as a texture coordinate, so the GPU interpolates the
// tint across the shard. (Per-vertex colors do not combine with an image
// shader and render black on Android; this is the Cloth Banner pattern.)
function makeTintRamp() {
  const surface = Skia.Surface.MakeOffscreen(256, 1);
  if (!surface) throw new Error("Unable to prepare the tint ramp");
  const canvas = surface.getCanvas();
  const paint = Skia.Paint();
  canvas.clear(Skia.Color("transparent"));
  for (let i = 0; i < 256; i++) {
    paint.setColor(Skia.Color(`rgba(255,255,255,${((i / 255) * 0.5).toFixed(4)})`));
    canvas.drawRect(Skia.XYWHRect(i, 0, 1, 1), paint);
  }
  surface.flush();
  const snapshot = surface.makeImageSnapshot();
  const copy = snapshot.makeNonTextureImage();
  snapshot.dispose();
  surface.dispose();
  paint.dispose();
  if (!copy) throw new Error("Unable to copy the tint ramp");
  return copy;
}

export function GlassShatter({
  image,
  imageScale = 2,
  width = 340,
  height = 460,
  shardCount = 360,
  slowMotion = false,
  reducedMotion,
  resetToken = 0,
  onFeedback,
  label = "A pane of glass over a harbor at sunrise. Tap or flick it to shatter it; the shards fall away.",
  style,
}: GlassShatterProps) {
  const [systemReduce, setSystemReduce] = useState(false);
  const reduce = reducedMotion ?? systemReduce;
  const sim = useSharedValue<World | null>(null);
  const brokenId = useSharedValue(0);
  const frame = useSharedValue(0);
  const inputs = useSharedValue<Ev[]>([]);
  const seen = useSharedValue(0);
  const slowM = useSharedValue(false);
  const reduceM = useSharedValue(false);
  const latest = useRef({ onFeedback });
  latest.current.onFeedback = onFeedback;
  const ring = useRef<Ev[]>([]);
  const counter = useRef(0);
  const brokenJS = useRef(false);
  const ramp = useMemo(() => makeTintRamp(), []);
  useEffect(() => () => ramp.dispose(), [ramp]);

  useEffect(() => {
    let alive = true;
    AccessibilityInfo.isReduceMotionEnabled()
      .then((v) => {
        if (alive) setSystemReduce(v);
      })
      .catch(() => {});
    const sub = AccessibilityInfo.addEventListener("reduceMotionChanged", setSystemReduce);
    return () => {
      alive = false;
      sub.remove();
    };
  }, []);
  useEffect(() => {
    slowM.value = slowMotion;
  }, [slowMotion, slowM]);
  useEffect(() => {
    reduceM.value = reduce;
  }, [reduce, reduceM]);

  const push = (k: number, x: number, y: number) => {
    counter.current += 1;
    const next = ring.current.concat({ id: counter.current, k, x, y }).slice(-12);
    ring.current = next;
    inputs.value = next;
  };
  const firstReset = useRef(true);
  useEffect(() => {
    if (firstReset.current) {
      firstReset.current = false;
      return;
    }
    brokenJS.current = false;
    push(1, 0, 0);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [resetToken]);

  const pan = useMemo(() => {
    const hit = (x: number, y: number) => {
      if (brokenJS.current) return;
      brokenJS.current = true;
      push(0, Math.max(2, Math.min(width - 2, x)), Math.max(2, Math.min(height - 2, y)));
      latest.current.onFeedback?.("hit");
    };
    return PanResponder.create({
      onStartShouldSetPanResponder: () => true,
      onPanResponderTerminationRequest: () => false,
      onPanResponderGrant: (evt) => hit(evt.nativeEvent.locationX, evt.nativeEvent.locationY),
    });
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [width, height]);

  useFrameCallback((info) => {
    const evs = inputs.value;
    for (let i = 0; i < evs.length; i++) {
      const e = evs[i];
      if (e.id <= seen.value) continue;
      seen.value = e.id;
      if (e.k === 0) {
        sim.value = createWorld({ width, height, hitX: e.x, hitY: e.y, seed: (e.id * 7919) % 100000, target: shardCount });
        brokenId.value = brokenId.value + 1;
      } else if (e.k === 1) {
        sim.value = null;
        brokenId.value = brokenId.value + 1;
      }
    }
    const w = sim.value;
    if (!w) return;
    if (!reduceM.value) {
      const dt = Math.min(48, info.timeSincePreviousFrame ?? 16.7) / 1000;
      stepWorld(w, dt * (slowM.value ? 0.25 : 1));
    }
    frame.value = frame.value + 1;
  });

  // Triangle fans, one per shard, rebuilt only when the pane breaks or resets.
  const indices = useDerivedValue(() => {
    brokenId.value;
    const w = sim.value;
    const out: number[] = [];
    if (!w) return out;
    let base = 0;
    for (let i = 0; i < w.bodies.length; i++) {
      const n = w.bodies[i].local.length;
      for (let t = 1; t < n - 1; t++) out.push(base, base + t, base + t + 1);
      base += n;
    }
    return out;
  });

  const mesh = useDerivedValue<Mesh>(() => {
    frame.value;
    brokenId.value;
    const w = sim.value;
    const xy: { x: number; y: number }[] = [];
    const tex: { x: number; y: number }[] = [];
    const tint: { x: number; y: number }[] = [];
    const path = Skia.Path.Make();
    if (!w) return { xy, tex, tint, path };
    const off = [0, 0];
    for (let i = 0; i < w.bodies.length; i++) {
      const b = w.bodies[i];
      const n = b.local.length;
      const c = Math.cos(b.a);
      const s = Math.sin(b.a);
      if (b.gone) {
        for (let k = 0; k < n; k++) {
          xy.push({ x: -9999, y: -9999 });
          tex.push({ x: 0, y: 0 });
          tint.push({ x: 0.5, y: 0.5 });
        }
        continue;
      }
      shardRefraction(b, off);
      const glint = b.held ? 0.18 : shardGlint(b);
      const tx = Math.max(0.5, Math.min(255.5, glint * 255 + 0.5));
      for (let k = 0; k < n; k++) {
        const p = b.local[k];
        const x = b.x + p.x * c - p.y * s;
        const y = b.y + p.x * s + p.y * c;
        xy.push({ x, y });
        // The glass is clear: each shard shows the picture behind where it is now, bent by its tilt.
        tex.push({ x: (x + off[0]) * imageScale, y: (y + off[1]) * imageScale });
        tint.push({ x: tx, y: 0.5 });
        if (k === 0) path.moveTo(x, y);
        else path.lineTo(x, y);
      }
      path.close();
    }
    return { xy, tex, tint, path };
  });
  const vertices = useDerivedValue(() => mesh.value.xy);
  const textures = useDerivedValue(() => mesh.value.tex);
  const tintTex = useDerivedValue(() => mesh.value.tint);
  const edges = useDerivedValue(() => mesh.value.path);
  const sheenOpacity = useDerivedValue(() => (brokenId.value >= 0 && sim.value ? 0 : 1));

  return (
    <View
      style={[{ width, height, borderRadius: 18, overflow: "hidden", backgroundColor: "#0b1426" }, style]}
      accessibilityLabel={label}
      accessibilityRole="image"
      {...pan.panHandlers}
    >
      {!reduce ? <CanvasKeepAlive /> : null}
      <Canvas pointerEvents="none" style={{ width, height }}>
        {/* The picture itself, always there behind the glass. */}
        <Rect x={0} y={0} width={width} height={height}>
          <ImageShader
            image={image}
            tx="clamp"
            ty="clamp"
            fit="fill"
            rect={{ x: 0, y: 0, width, height }}
            sampling={{ filter: FilterMode.Linear, mipmap: MipmapMode.Linear }}
          />
        </Rect>
        {/* Whole pane: a faint sheen and a bright rim. */}
        <RoundedRect x={0.5} y={0.5} width={width - 1} height={height - 1} r={18} opacity={sheenOpacity} color="transparent">
          <LinearGradient start={vec(0, 0)} end={vec(width * 0.8, height)} colors={["#ffffff26", "#ffffff08", "#ffffff1c"]} />
        </RoundedRect>
        <RoundedRect x={1} y={1} width={width - 2} height={height - 2} r={18} opacity={sheenOpacity} style="stroke" strokeWidth={1.2} color="#ffffff55" />
        {/* Broken pane: every shard shows the picture shifted by its tilt, with a tint that carries the glints. */}
        <Vertices vertices={vertices} textures={textures} indices={indices} mode="triangles">
          <ImageShader
            image={image}
            tx="clamp"
            ty="clamp"
            sampling={{ filter: FilterMode.Linear, mipmap: MipmapMode.Linear }}
          />
        </Vertices>
        <Vertices vertices={vertices} textures={tintTex} indices={indices} mode="triangles">
          <ImageShader image={ramp} tx="clamp" ty="clamp" sampling={{ filter: FilterMode.Linear, mipmap: MipmapMode.None }} />
        </Vertices>
        <Path path={edges} style="stroke" strokeWidth={0.9} strokeJoin="round" color="#ffffffcc" />
        <Path path={edges} style="stroke" strokeWidth={0.4} strokeJoin="round" color="#1b2a4a99" />
      </Canvas>
    </View>
  );
}

// Fracture geometry for Glass Shatter. Pure functions, no React Native imports.
// The pane breaks the way tempered and annealed glass cracks around an impact:
// radial spokes and concentric rings of sites near the hit, fewer and larger
// pieces further away. Each shard is a convex Voronoi cell of those sites.

export type Vec = { x: number; y: number };
export type Shard = {
  /** Convex polygon, counter-clockwise, in pane coordinates (the intact position). */
  poly: Vec[];
  /** Centroid of the polygon in pane coordinates. */
  cx: number;
  cy: number;
  /** Polygon area. */
  area: number;
  /** Distance from the impact point to the centroid. */
  dist: number;
};

export function mulberry32(seed: number): () => number {
  'worklet';
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

/** Clip a convex polygon to the half-plane {p : (p - m) . n <= 0}. Sutherland-Hodgman. */
export function clipHalfPlane(poly: Vec[], mx: number, my: number, nx: number, ny: number): Vec[] {
  'worklet';
  const out: Vec[] = [];
  const n = poly.length;
  for (let i = 0; i < n; i++) {
    const a = poly[i];
    const b = poly[(i + 1) % n];
    const da = (a.x - mx) * nx + (a.y - my) * ny;
    const db = (b.x - mx) * nx + (b.y - my) * ny;
    if (da <= 0) out.push(a);
    if ((da < 0 && db > 0) || (da > 0 && db < 0)) {
      const t = da / (da - db);
      out.push({ x: a.x + (b.x - a.x) * t, y: a.y + (b.y - a.y) * t });
    }
  }
  return out;
}

export function polyArea(p: Vec[]): number {
  'worklet';
  let s = 0;
  for (let i = 0; i < p.length; i++) {
    const a = p[i];
    const b = p[(i + 1) % p.length];
    s += a.x * b.y - b.x * a.y;
  }
  return s / 2;
}

export function polyCentroid(p: Vec[]): Vec {
  'worklet';
  let cx = 0;
  let cy = 0;
  let s = 0;
  for (let i = 0; i < p.length; i++) {
    const a = p[i];
    const b = p[(i + 1) % p.length];
    const c = a.x * b.y - b.x * a.y;
    s += c;
    cx += (a.x + b.x) * c;
    cy += (a.y + b.y) * c;
  }
  if (Math.abs(s) < 1e-9) return { x: p[0].x, y: p[0].y };
  return { x: cx / (3 * s), y: cy / (3 * s) };
}

export type FractureOptions = {
  /** Pane width and height in points. */
  width: number;
  height: number;
  /** Impact point in pane coordinates. */
  hitX: number;
  hitY: number;
  /** Seed for the jitter, so the same hit always breaks the same way. */
  seed?: number;
  /** Approximate shard count (the pattern lands within about 15% of it). */
  target?: number;
};

/** Sites: a dense core at the hit, rings that thin out, plus a sparse far field. */
export function fractureSites(o: FractureOptions): Vec[] {
  'worklet';
  const rnd = mulberry32(o.seed ?? 1);
  const target = o.target ?? 110;
  const sites: Vec[] = [{ x: o.hitX, y: o.hitY }];
  const reach = Math.hypot(Math.max(o.hitX, o.width - o.hitX), Math.max(o.hitY, o.height - o.hitY));
  // Radii grow geometrically, so pieces near the hit are small.
  const growth = 1.42;
  const r0 = reach * 0.045;
  let r = r0;
  let ring = 0;
  while (r < reach * 1.02 && sites.length < target * 1.6) {
    // Spoke count grows with radius slower than circumference: bigger far pieces.
    const spokes = Math.max(5, Math.round(6 + ring * 2.2));
    const phase = rnd() * Math.PI * 2;
    for (let k = 0; k < spokes; k++) {
      const ang = phase + (k / spokes) * Math.PI * 2 + (rnd() - 0.5) * (Math.PI * 2 / spokes) * 0.55;
      const rr = r * (0.86 + rnd() * 0.3);
      const x = o.hitX + Math.cos(ang) * rr;
      const y = o.hitY + Math.sin(ang) * rr;
      if (x > -reach * 0.05 && x < o.width * 1.05 && y > -reach * 0.05 && y < o.height * 1.05) sites.push({ x, y });
    }
    r *= growth;
    ring++;
  }
  // Fill the far field up to the target with jittered samples (rejection by min distance).
  const minD = Math.sqrt((o.width * o.height) / Math.max(target, 20)) * 0.55;
  let tries = 0;
  while (sites.length < target && tries < 4000) {
    tries++;
    const x = rnd() * o.width;
    const y = rnd() * o.height;
    let ok = true;
    for (const s of sites) {
      if ((s.x - x) ** 2 + (s.y - y) ** 2 < minD * minD) {
        ok = false;
        break;
      }
    }
    if (ok) sites.push({ x, y });
  }
  return sites;
}

/** Voronoi cells of `sites`, clipped to the pane rectangle. Drops slivers. */
export function fracturePane(o: FractureOptions): Shard[] {
  'worklet';
  const sites = fractureSites(o);
  const rect: Vec[] = [
    { x: 0, y: 0 },
    { x: o.width, y: 0 },
    { x: o.width, y: o.height },
    { x: 0, y: o.height },
  ];
  const shards: Shard[] = [];
  const minArea = (o.width * o.height) / 4000;
  for (let i = 0; i < sites.length; i++) {
    let poly = rect;
    const si = sites[i];
    for (let j = 0; j < sites.length && poly.length >= 3; j++) {
      if (j === i) continue;
      const sj = sites[j];
      const nx = sj.x - si.x;
      const ny = sj.y - si.y;
      const mx = (si.x + sj.x) / 2;
      const my = (si.y + sj.y) / 2;
      poly = clipHalfPlane(poly, mx, my, nx, ny);
    }
    if (poly.length < 3) continue;
    const area = polyArea(poly);
    if (area < minArea) continue;
    const c = polyCentroid(poly);
    shards.push({ poly, cx: c.x, cy: c.y, area, dist: Math.hypot(c.x - o.hitX, c.y - o.hitY) });
  }
  return shards;
}

export type Body = {
  /** Centroid position and rotation. */
  x: number; y: number; a: number;
  vx: number; vy: number; w: number;
  invM: number; invI: number;
  /** Visual polygon relative to the centroid (counter-clockwise). */
  local: Vec[];
  /** Collision polygon: the visual one shrunk a hair, so touching cells start separated. */
  hull: Vec[];
  /** Cached world-space hull. */
  wx: number[]; wy: number[];
  /** Pane position of the centroid before the break. */
  homeX: number; homeY: number;
  radius: number;
  sleep: number;
  asleep: boolean;
  /** Still hanging in the frame: acts as a fixed obstacle until the crack reaches it. */
  held: boolean;
  releaseAt: number;
  kx: number; ky: number; kw: number;
  /** Fell out of the frame; no longer simulated or drawn. */
  gone: boolean;
};

export type World = {
  bodies: Body[];
  width: number;
  height: number;
  gravity: number;
  time: number;
  hit: Vec;
  /** Peak per-frame penetration seen, a diagnostic. */
  maxPen: number;
  contacts: number;
  /** Bodies sorted by left edge for the sweep. */
  order: Body[];
};

const SHRINK = 1.2;
const CRACK_SPEED = 780;

export function updateWorldHull(b: Body) {
  'worklet';
  const c = Math.cos(b.a);
  const s = Math.sin(b.a);
  for (let i = 0; i < b.hull.length; i++) {
    const p = b.hull[i];
    b.wx[i] = b.x + p.x * c - p.y * s;
    b.wy[i] = b.y + p.x * s + p.y * c;
  }
}

export function createWorld(o: FractureOptions & { gravity?: number }): World {
  'worklet';
  const shards = fracturePane(o);
  const rnd = mulberry32((o.seed ?? 1) + 101);
  const bodies: Body[] = shards.map((s) => {
    const local = s.poly.map((p) => ({ x: p.x - s.cx, y: p.y - s.cy }));
    const hull = local.map((p) => {
      const d = Math.hypot(p.x, p.y) || 1;
      const k = Math.max(0, 1 - SHRINK / d);
      return { x: p.x * k, y: p.y * k };
    });
    const mass = s.area * 0.01;
    // Polar moment about the centroid for a polygon (density 0.01).
    let num = 0;
    let den = 0;
    for (let i = 0; i < local.length; i++) {
      const p = local[i];
      const q = local[(i + 1) % local.length];
      const c = Math.abs(p.x * q.y - q.x * p.y);
      num += c * (p.x * p.x + p.y * p.y + p.x * q.x + p.y * q.y + q.x * q.x + q.y * q.y);
      den += c;
    }
    const inertia = den > 0 ? (mass * num) / (6 * den) : mass;
    let radius = 0;
    for (const p of local) radius = Math.max(radius, Math.hypot(p.x, p.y));
    return {
      x: s.cx, y: s.cy, a: 0, vx: 0, vy: 0, w: 0,
      invM: 1 / mass, invI: 1 / Math.max(inertia, 1e-6),
      local, hull, wx: hull.map(() => 0), wy: hull.map(() => 0),
      homeX: s.cx, homeY: s.cy, radius, sleep: 0, asleep: false,
      held: true, releaseAt: 0, kx: 0, ky: 0, kw: 0, gone: false,
    };
  });
  const world: World = {
    bodies, width: o.width, height: o.height, gravity: o.gravity ?? 1500,
    time: 0, hit: { x: o.hitX, y: o.hitY }, maxPen: 0, contacts: 0, order: bodies.slice(),
  };
  // The blow: shards leave the impact point radially. Close pieces get a hard
  // shove, far pieces just drop and tip, with a little scatter.
  const reach = Math.hypot(o.width, o.height);
  for (const b of bodies) {
    const dx = b.x - o.hitX;
    const dy = b.y - o.hitY;
    const d = Math.hypot(dx, dy) || 1;
    const fall = Math.exp(-d / (reach * 0.22));
    const kick = 520 * fall + 40;
    b.kx = (dx / d) * kick * (0.8 + rnd() * 0.4);
    b.ky = (dy / d) * kick * (0.8 + rnd() * 0.4) - 90 * fall;
    b.kw = (rnd() - 0.5) * 9 * (0.25 + fall);
    // The crack runs outward from the hit; a cell lets go when it arrives.
    b.releaseAt = d / CRACK_SPEED + rnd() * 0.04;
    updateWorldHull(b);
  }
  return world;
}



type Contact = {
  a: Body; b: Body | null;
  nx: number; ny: number; // from a toward b (or out of the wall for b === null: pushes a)
  px: number; py: number; // world contact point
  pen: number;
  ra: Vec; rb: Vec;
  jn: number; jt: number;
  mn: number; mt: number;
  bias: number;
};

/** Best separating axis of A's edges against B. Returns [separation, edgeIndex]. */
function maxSeparation(A: Body, B: Body): [number, number] {
  'worklet';
  let best = -Infinity;
  let idx = 0;
  const n = A.wx.length;
  for (let i = 0; i < n; i++) {
    const j = (i + 1) % n;
    let nx = A.wy[j] - A.wy[i];
    let ny = -(A.wx[j] - A.wx[i]);
    const l = Math.hypot(nx, ny) || 1;
    nx /= l;
    ny /= l;
    let min = Infinity;
    for (let k = 0; k < B.wx.length; k++) {
      const d = (B.wx[k] - A.wx[i]) * nx + (B.wy[k] - A.wy[i]) * ny;
      if (d < min) min = d;
    }
    if (min > best) {
      best = min;
      idx = i;
    }
  }
  return [best, idx];
}

/** Polygon-polygon manifold by SAT and incident-edge clipping. Appends contacts. */
function collide(A: Body, B: Body, out: Contact[]) {
  'worklet';
  const [sepA, ia] = maxSeparation(A, B);
  if (sepA > 0) return;
  const [sepB, ib] = maxSeparation(B, A);
  if (sepB > 0) return;
  // Reference body owns the face with the shallowest penetration.
  let flip = false;
  let R = A;
  let I = B;
  let ri = ia;
  if (sepB > sepA + 1e-4) {
    flip = true;
    R = B;
    I = A;
    ri = ib;
  }
  const rn = R.wx.length;
  const r1x = R.wx[ri], r1y = R.wy[ri];
  const r2x = R.wx[(ri + 1) % rn], r2y = R.wy[(ri + 1) % rn];
  let tx = r2x - r1x, ty = r2y - r1y;
  const tl = Math.hypot(tx, ty) || 1;
  tx /= tl; ty /= tl;
  const nx = ty, ny = -tx; // outward normal of the reference face
  // Incident edge: the edge of I most anti-parallel to the reference normal.
  const inn = I.wx.length;
  let ii = 0;
  let minDot = Infinity;
  for (let i = 0; i < inn; i++) {
    const j = (i + 1) % inn;
    let ex = I.wy[j] - I.wy[i];
    let ey = -(I.wx[j] - I.wx[i]);
    const l = Math.hypot(ex, ey) || 1;
    ex /= l; ey /= l;
    const d = ex * nx + ey * ny;
    if (d < minDot) { minDot = d; ii = i; }
  }
  let p1 = { x: I.wx[ii], y: I.wy[ii] };
  let p2 = { x: I.wx[(ii + 1) % inn], y: I.wy[(ii + 1) % inn] };
  // Clip the incident edge to the side planes of the reference edge.
  const clip = (a: Vec, b: Vec, dx: number, dy: number, off: number): [Vec, Vec] | null => {
    const da = a.x * dx + a.y * dy - off;
    const db = b.x * dx + b.y * dy - off;
    const pts: Vec[] = [];
    if (da <= 0) pts.push(a);
    if (db <= 0) pts.push(b);
    if (da * db < 0) {
      const t = da / (da - db);
      pts.push({ x: a.x + (b.x - a.x) * t, y: a.y + (b.y - a.y) * t });
    }
    return pts.length < 2 ? null : [pts[0], pts[1]];
  };
  let c = clip(p1, p2, -tx, -ty, -(r1x * tx + r1y * ty));
  if (!c) return;
  c = clip(c[0], c[1], tx, ty, r2x * tx + r2y * ty);
  if (!c) return;
  const faceOff = r1x * nx + r1y * ny;
  // Contact normal points from A toward B.
  const cnx = flip ? -nx : nx;
  const cny = flip ? -ny : ny;
  for (const p of c) {
    const sep = p.x * nx + p.y * ny - faceOff;
    if (sep > 0) continue;
    out.push({
      a: A, b: B, nx: cnx, ny: cny, px: p.x, py: p.y, pen: -sep,
      ra: { x: p.x - A.x, y: p.y - A.y }, rb: { x: p.x - B.x, y: p.y - B.y },
      jn: 0, jt: 0, mn: 0, mt: 0, bias: 0,
    });
  }
}

const FRICTION = 0.5;
const RESTITUTION = 0.25;
const SLOP = 0.3;
const BAUMGARTE = 0.2;
const MAX_PUSH = 140;

function wallContacts(a: Body, W: number, H: number, out: Contact[]) {
  'worklet';
  for (let i = 0; i < a.wx.length; i++) {
    const x = a.wx[i], y = a.wy[i];
    // n points from the body into the wall.
    const push = (nx: number, ny: number, pen: number) =>
      out.push({
        a, b: null, nx, ny, px: x, py: y, pen,
        ra: { x: x - a.x, y: y - a.y }, rb: { x: 0, y: 0 },
        jn: 0, jt: 0, mn: 0, mt: 0, bias: 0,
      });
    if (y > H) push(0, 1, y - H);
    if (x < 0) push(-1, 0, -x);
    if (x > W) push(1, 0, x - W);
  }
}

function relVel(ct: Contact): [number, number] {
  'worklet';
  const { a, b } = ct;
  const vax = a.vx - a.w * ct.ra.y, vay = a.vy + a.w * ct.ra.x;
  if (!b) return [-vax, -vay];
  const vbx = b.vx - b.w * ct.rb.y, vby = b.vy + b.w * ct.rb.x;
  return [vbx - vax, vby - vay];
}

function prep(ct: Contact, dt: number) {
  'worklet';
  const { a, b } = ct;
  const nx = ct.nx, ny = ct.ny;
  const tx = -ny, ty = nx;
  const rnA = ct.ra.x * ny - ct.ra.y * nx;
  const rtA = ct.ra.x * ty - ct.ra.y * tx;
  let k = a.invM + a.invI * rnA * rnA;
  let kt = a.invM + a.invI * rtA * rtA;
  if (b) {
    const rnB = ct.rb.x * ny - ct.rb.y * nx;
    const rtB = ct.rb.x * ty - ct.rb.y * tx;
    k += b.invM + b.invI * rnB * rnB;
    kt += b.invM + b.invI * rtB * rtB;
  }
  ct.mn = k > 0 ? 1 / k : 0;
  ct.mt = kt > 0 ? 1 / kt : 0;
  const [rx, ry] = relVel(ct);
  const vn = rx * nx + ry * ny; // negative = closing
  const bounce = vn < -120 ? -RESTITUTION * vn : 0;
  const push = Math.min(MAX_PUSH, (BAUMGARTE * Math.max(ct.pen - SLOP, 0)) / dt);
  ct.bias = Math.max(bounce, push);
}

function applyImpulse(ct: Contact, jx: number, jy: number) {
  'worklet';
  const { a, b } = ct;
  a.vx -= a.invM * jx; a.vy -= a.invM * jy;
  a.w -= a.invI * (ct.ra.x * jy - ct.ra.y * jx);
  if (b) {
    b.vx += b.invM * jx; b.vy += b.invM * jy;
    b.w += b.invI * (ct.rb.x * jy - ct.rb.y * jx);
  }
}

function solve(ct: Contact) {
  'worklet';
  const nx = ct.nx, ny = ct.ny;
  const tx = -ny, ty = nx;
  let [rx, ry] = relVel(ct);
  let dj = ct.mn * (ct.bias - (rx * nx + ry * ny));
  const old = ct.jn;
  ct.jn = Math.max(old + dj, 0);
  dj = ct.jn - old;
  applyImpulse(ct, nx * dj, ny * dj);
  [rx, ry] = relVel(ct);
  let djt = -ct.mt * (rx * tx + ry * ty);
  const maxF = FRICTION * ct.jn;
  const oldT = ct.jt;
  ct.jt = Math.max(-maxF, Math.min(maxF, oldT + djt));
  djt = ct.jt - oldT;
  applyImpulse(ct, tx * djt, ty * djt);
}

const SUB = 3;
const FIXED = 1 / 180;
const SLEEP_V = 6;
const SLEEP_W = 0.25;
const SLEEP_T = 0.5;


function stepFixed(w: World, dt: number) {
  'worklet';
  const bodies = w.bodies;
  w.time += dt;
  for (const b of bodies) {
    if (b.gone) continue;
    if (b.held && w.time >= b.releaseAt) {
      b.held = false;
      b.vx = b.kx; b.vy = b.ky; b.w = b.kw;
    }
    if (b.held || b.asleep) continue;
    b.vy += w.gravity * dt;
    // Air and spin damping keep the pile from ringing.
    b.vx *= 1 - 0.05 * dt;
    b.vy *= 1 - 0.05 * dt;
    b.w *= 1 - 0.35 * dt;
  }
  // Broadphase: sweep over bodies sorted by their left edge (insertion sort,
  // the order barely changes between steps), then bounding-circle test, then SAT.
  const contacts: Contact[] = [];
  const order = w.order;
  for (let i = 1; i < order.length; i++) {
    const v = order[i];
    const key = v.x - v.radius;
    let j = i - 1;
    while (j >= 0 && order[j].x - order[j].radius > key) {
      order[j + 1] = order[j];
      j--;
    }
    order[j + 1] = v;
  }
  for (let i = 0; i < order.length; i++) {
    const a = order[i];
    if (a.gone) continue;
    const aMoving = !(a.asleep || a.held);
    const aRight = a.x + a.radius;
    for (let j = i + 1; j < order.length; j++) {
      const b = order[j];
      if (b.x - b.radius > aRight) break;
      if (b.gone) continue;
      if (!aMoving && (b.asleep || b.held)) continue;
      const dx = b.x - a.x, dy = b.y - a.y;
      const rr = a.radius + b.radius;
      if (dx * dx + dy * dy > rr * rr) continue;
      collide(a, b, contacts);
    }
  }
  w.contacts = contacts.length;
  for (const ct of contacts) {
    // A moving body touching a sleeper wakes it.
    if (ct.b && !ct.a.held && !ct.b.held && (ct.a.asleep !== ct.b.asleep)) {
      const m = ct.a.asleep ? ct.b : ct.a;
      if (m.vx * m.vx + m.vy * m.vy > 40 * 40) { ct.a.asleep = false; ct.b.asleep = false; ct.a.sleep = ct.b.sleep = 0; }
    }
    prep(ct, dt);
    if (ct.pen > w.maxPen) w.maxPen = ct.pen;
  }
  // Sleepers act as heavy anchors (no inverse mass) so a resting pile holds still.
  const anchored: Body[] = [];
  const am: number[] = [];
  const ai: number[] = [];
  for (const b of bodies) if (!b.gone && (b.asleep || b.held)) { anchored.push(b); am.push(b.invM); ai.push(b.invI); b.invM = 0; b.invI = 0; }
  for (let it = 0; it < 14; it++) for (const ct of contacts) solve(ct);
  for (let q = 0; q < anchored.length; q++) { anchored[q].invM = am[q]; anchored[q].invI = ai[q]; }
  for (const b of bodies) {
    if (b.gone || b.held || b.asleep) continue;
    b.x += b.vx * dt;
    b.y += b.vy * dt;
    b.a += b.w * dt;
    const sp2 = b.vx * b.vx + b.vy * b.vy;
    if (sp2 < SLEEP_V * SLEEP_V && Math.abs(b.w) < SLEEP_W) {
      b.sleep += dt;
      if (b.sleep > SLEEP_T) { b.asleep = true; b.vx = b.vy = b.w = 0; }
    } else b.sleep = 0;
    updateWorldHull(b);
    if (b.y - b.radius > w.height + 60 || b.x + b.radius < -w.width * 0.6 || b.x - b.radius > w.width * 1.6) b.gone = true;
  }
}

export function stepWorld(w: World, dtFrame: number) {
  'worklet';
  let remaining = Math.min(dtFrame, 1 / 20);
  while (remaining > 1e-6) {
    const dt = Math.min(FIXED * SUB / SUB, remaining);
    remaining -= dt;
    stepFixed(w, dt);
  }
}

export function allAsleep(w: World): boolean {
  'worklet';
  for (const b of w.bodies) if (!b.gone && !b.asleep) return false;
  return true;
}

/** Refraction: a glass edge tilting in its fall shifts the picture behind it. Not ray tracing: a tilt-driven
 * offset of the texture lookup, a visual approximation of a thin pane bending light. */
export function shardRefraction(b: Body, out: number[]) {
  'worklet';
  const k = b.held ? 0 : 1;
  const wob = b.a * 1.7 + b.homeX * 0.031 + b.homeY * 0.017;
  out[0] = Math.sin(wob) * 7 * k;
  out[1] = Math.cos(wob * 0.8 + 1.3) * 7 * k;
}

/** Glint brightness 0..1 from the shard's current angle, a fixed light from the upper left. */
export function shardGlint(b: Body): number {
  'worklet';
  const g = 0.5 + 0.5 * Math.sin(b.a * 2.3 + b.homeX * 0.05 + b.homeY * 0.03);
  return g * g;
}

// The picture behind the glass, as plain data in pane points: a harbor at
// sunrise with a city skyline and a sun path on the water. One description
// feeds both the Skia texture and the website's Canvas 2D preview.
export const PANE_W = 340;
export const PANE_H = 460;

export type DesignItem =
  | { k: "vgrad"; x: number; y: number; w: number; h: number; from: string; to: string; mid?: string }
  | { k: "rect"; x: number; y: number; w: number; h: number; color: string }
  | { k: "circle"; x: number; y: number; r: number; color: string }
  | { k: "poly"; points: number[]; color: string };

function skyline(): DesignItem[] {
  const out: DesignItem[] = [];
  // [x, width, height] towers standing on the shoreline y = 292.
  const towers: [number, number, number][] = [
    [0, 26, 74], [24, 20, 108], [42, 30, 66], [70, 18, 130], [86, 26, 90], [110, 34, 58], [142, 22, 150],
    [162, 28, 84], [188, 20, 116], [206, 32, 70], [236, 24, 138], [258, 30, 92], [286, 22, 60], [306, 34, 102],
  ];
  for (const [x, w, h] of towers) {
    out.push({ k: "rect", x, y: 292 - h, w, h, color: h > 110 ? "#1c2a3f" : "#223249" });
    // lit windows
    for (let wy = 292 - h + 8; wy < 284; wy += 12) {
      for (let wx = x + 4; wx < x + w - 5; wx += 8) {
        if ((wx * 7 + wy * 3) % 5 < 2) out.push({ k: "rect", x: wx, y: wy, w: 3, h: 4, color: "#ffd9a0cc" });
      }
    }
  }
  return out;
}

export function glassSceneDesign(): DesignItem[] {
  const W = PANE_W;
  return [
